
    const API_BASE_URL=(window.VAMORA_API_BASE_URL||'https://61a8-197-52-104-51.ngrok-free.app/api').replace(/\/+$/,'');
    async function apiRequest(path,{method='GET',body,authenticated=false}={}){
      const token=localStorage.getItem('vamora_access_token');
      const headers={Accept:'application/json', 'ngrok-skip-browser-warning': 'true'};
      if(body)headers['Content-Type']='application/json';
      if(authenticated&&token)headers.Authorization='Bearer '+token;
      let response;
      try{response=await fetch(API_BASE_URL+path,{method,headers,body:body?JSON.stringify(body):undefined});}
      catch{throw new Error('Unable to reach the API. Check the Laravel API URL and CORS settings.');}
      const data=await response.json().catch(()=>({}));
      if(!response.ok){
        const validation=Object.values(data.errors||{}).flat().find(Boolean);
        throw new Error(validation||data.message||'The request could not be completed.');
      }
      return data;
    }
    function setBusy(button,busy,label){
      if(!button)return;
      if(busy){button.dataset.label=button.textContent;button.disabled=true;button.textContent=label||'Please wait…';}
      else{button.disabled=false;button.textContent=button.dataset.label||button.textContent;}
    }
    function saveSession(payload){
      const token=payload?.token||payload?.data?.token||payload?.access_token;
      if(token)localStorage.setItem('vamora_access_token',token);
      const clientId=payload?.client?.id||payload?.data?.client?.id||payload?.user?.client?.id;
      if(clientId)localStorage.setItem('vamora_client_id',clientId);
      const user = payload?.user || payload?.data?.user || payload?.client || payload?.data?.client;
      if(user) {
         localStorage.setItem('vamora_user_name', ((user.first_name || user.name || 'Traveler') + ' ' + (user.last_name || '')).trim());
         localStorage.setItem('vamora_user_email', user.email || '');
      }
    }
    async function registerWithApi(event){
      event.preventDefault();
      const form=event.currentTarget,submit=document.getElementById('registerSubmit');
      const values=Object.fromEntries(new FormData(form).entries());
      if(values.password!==values.password_confirmation){toast('Passwords do not match.');return;}
      setBusy(submit,true,'Creating account…');
      try{
        const result=await apiRequest('/auth/register',{method:'POST',body:{first_name:values.first_name,last_name:values.last_name,email:values.email,phone:values.phone,birth_date:values.birth_date,long:values.long,latittude:values.latittude,password:values.password,password_confirmation:values.password_confirmation}});
        saveSession(result);
        toast(result.message||'Account created successfully.');
        show('dashboard');
      }catch(error){toast(error.message);}
      finally{setBusy(submit,false);}
    }
    async function loginWithApi(){
      const email=document.getElementById('loginEmail')?.value.trim(),password=document.getElementById('loginPassword')?.value;
      const submit=document.getElementById('loginSubmit');
      if(!email||!password){toast('Enter your email and password.');return;}
      setBusy(submit,true,'Signing in…');
      try{
        const result=await apiRequest('/auth/login',{method:'POST',body:{email,password}});
        saveSession(result);
        toast(result.message||'Welcome back.');
        show('dashboard');
      }catch(error){toast(error.message);}
      finally{setBusy(submit,false);}
    }
    const trips=[['Istanbul City Escape','5 Days · Culture & food','From $620','cover1'],['Coastal Athens','4 Days · Sun & history','From $540','cover2'],['Bali Slow Living','8 Days · Nature & wellness','From $890','cover3']]; let selectedTrip=trips[0];
    function openTrip(i){selectedTrip=trips[i];show('trip-details')}
    function card(t,i){return `<article class="trip-card" onclick="openTrip(${i})"><div class="cover ${t[3]}"><span class="tag">${i===0?'Popular':'Ready trip'}</span><button class="heart" aria-label="Save ${t[0]} to favourites" onclick="event.stopPropagation();toggleFavourite(this,'${t[0]}')">♡</button></div><div class="trip-body"><h3>${t[0]}</h3><p>${t[1]}</p><div class="card-bottom"><span class="price">${t[2]}</span><button class="btn outline" onclick="event.stopPropagation();openTrip(${i})">View trip</button></div></div></article>`}
    document.getElementById('homeCards').innerHTML=trips.map(card).join(''); document.getElementById('dashboardCards').innerHTML=trips.slice(0,2).map(card).join('');
    const nav=[['dashboard','⌂','Overview'],['trips','◈','Explore trips'],['explore-map','⌖','Explore map'],['create-trip','＋','Create a trip'],['favourites','♡','Favourites'],['compare','⇄','Compare'],['booking','▣','Bookings'],['reviews','★','Reviews']];
