    function renderAppSidebar(active){const side=document.getElementById('appSidebar');if(!side)return;const on=sidebarPages.has(active);document.body.classList.toggle('with-app-sidebar',on);if(!on){side.innerHTML='';return}const discover=[['trips','◈','Explore trips'],['explore-map','⌖','Explore map'],['create-trip','⊞','Create a trip']];const travel=[['favourites','♡','Favourites'],['compare','⇄','Compare'],['booking','▣','Bookings'],['reviews','☆','Reviews']];const section=(title,items)=>'<div class="app-side-section">'+title+'</div><div class="app-side-list">'+items.map(x=>'<button class="app-side-link '+(active===x[0]?'active':'')+'" onclick="show(\''+x[0]+'\')"><i>'+x[1]+'</i><strong>'+x[2]+'</strong></button>').join('')+'</div>';side.innerHTML='<div class="app-side-top"><div class="app-side-brand" onclick="show(\'home\')"><b>✈</b><span>Voyago</span></div><button class="app-side-collapse" aria-label="Toggle sidebar" onclick="toggleAppSidebar()">‹</button></div>'+section('DISCOVER',discover)+'<div class="app-side-divider"></div>'+section('MY TRAVEL',travel);}
    function toggleAppSidebar(){document.body.classList.toggle('collapsed');document.getElementById('appSidebar')?.classList.toggle('open');if(travelMap)setTimeout(()=>travelMap.invalidateSize(),250)}
    function show(id){const page=document.getElementById(id);if(!page){toast('This page is not available yet.');return;}document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));page.classList.add('active');renderAppSidebar(id);window.scrollTo(0,0);document.querySelectorAll('app-shell').forEach(renderShell);document.querySelectorAll('.detail-hero').forEach(hero=>hero.classList.add(selectedTrip[3]));if(id==='explore-map')setTimeout(initExploreMap,0);if(id==='booking')setTimeout(applyBookingSelection,0);const storedName=(localStorage.getItem('vamora_user_name')||'Traveler').trim();const first=storedName.split(' ')[0];const initials=first.substring(0,2).toUpperCase();const greetingEl=document.getElementById('userGreetingName');if(greetingEl)greetingEl.textContent=first;const avatarEl=document.getElementById('navAvatarName');if(avatarEl)avatarEl.textContent=initials;}
    function toast(msg){const x=document.createElement('div');x.textContent=msg;x.style.cssText='position:fixed;bottom:24px;right:24px;background:#0B1F4A;color:white;padding:14px 18px;border-radius:10px;box-shadow:0 10px 25px #0003;z-index:9';document.body.appendChild(x);setTimeout(()=>x.remove(),2200)}
