function bookingShell(){return `<nav class="booking-nav"><div class="booking-nav-inner"><div class="booking-brand" onclick="show('home')"><span class="booking-mark">✈</span>Voy<span>ago</span></div><div class="booking-navlinks"><a onclick="show('trips')">Explore</a><a onclick="show('trips')">Hotels</a><a onclick="show('trips')">Trips</a><a onclick="show('favourites')">Favourites</a></div><div class="booking-nav-actions"><span class="joy-dot">✦</span><b>Joy</b><button class="meet-joy" onclick="show('create-trip')">Meet Joy</button><span class="booking-avatar">MA</span></div></div></nav><main class="booking-page"><div class="booking-steps"><div class="booking-step done"><div class="step-num">1</div>Your stay</div><div class="booking-step active"><div class="step-num">2</div>Guest details</div><div class="booking-step"><div class="step-num">3</div>Payment</div><div class="booking-step"><div class="step-num">4</div>Confirmation</div></div><div class="booking-grid"><section><h1 class="booking-title">Complete your booking</h1><p class="booking-subtitle">You’re one step away from your perfect stay.</p><div class="booking-card"><h2>Guest details</h2><div class="booking-fields"><div class="booking-field"><label>First name</label><input placeholder="Enter first name"></div><div class="booking-field"><label>Last name</label><input placeholder="Enter last name"></div><div class="booking-field"><label>Email address</label><input type="email" placeholder="Enter email address"></div><div class="booking-field"><label>Phone number</label><div class="phone"><select><option>🇪🇬 +20</option><option>🇺🇸 +1</option><option>🇦🇪 +971</option></select><input placeholder="(555) 123-4567"></div></div><div class="booking-field"><label>Country/Region</label><select><option>Select country/region</option><option>Egypt</option><option>United Arab Emirates</option><option>United States</option></select></div></div></div><div class="booking-card"><h2>Special requests</h2><label class="request-label">Special requests <span>(optional)</span><span id="requestCount">0/500</span></label><textarea maxlength="500" oninput="document.getElementById('requestCount').textContent=this.value.length+'/500'" placeholder="Let us know if you have any special requests..."></textarea><div class="booking-options"><div class="booking-field"><label>Arrival time <span style="font-weight:400;color:#74839c">(optional)</span></label><select><option>Select arrival time</option><option>12:00 PM – 3:00 PM</option><option>3:00 PM – 7:00 PM</option><option>After 7:00 PM</option></select></div><label class="checkline"><input type="checkbox"> I would like airport pickup</label></div></div><div class="booking-security"><span class="security-icon">♢</span><span><b>Your information is secure and encrypted</b><br>We use industry-standard encryption to protect your personal data.</span></div></section><aside><div class="booking-summary"><div class="booking-summary-image"></div><div class="booking-summary-body"><h2>Azure Bay Resort</h2><div class="rating">★★★★★</div><div class="location">⌖&nbsp; Nusa Dua, Bali, Indonesia</div><div class="joy-recommend"><span class="joy-dot" style="width:20px;height:20px;font-size:10px">✦</span> Joy recommends</div><div class="summary-divider"></div><div class="stay-row"><span>▣ &nbsp; Jun 10 – Jun 15, 2026</span><b>5 nights</b></div><div class="stay-meta">♙ &nbsp; 2 Guests, 1 Room<br>▱ &nbsp; Ocean View King Room</div><div class="stay-perks"><span>☕ &nbsp; Breakfast included</span><span>♢ &nbsp; Free cancellation</span></div><div class="summary-divider"></div><div class="price-row"><span>$198 × 5 nights</span><b>$990</b></div><div class="price-row"><span>Taxes and fees</span><b>$118</b></div><div class="price-row"><span>Voyago service fee</span><b>$0</b></div><div class="price-row total"><span>Total</span><span>$1,108 USD</span></div><button class="booking-continue" onclick="toast('Moving to secure payment…')">Continue to payment</button><div class="not-charged">♙ &nbsp; You won’t be charged yet</div><div class="payment-label">Secure payment powered by</div><div class="payment-badges"><span class="payment-badge paymob">PAYMOB</span></div></div></div></aside></div></main>`}
function mapShell(){return `<nav class="notice-nav"><div class="booking-nav-inner"><div class="booking-brand" onclick="show('home')"><span class="booking-mark">✈</span>Voy<span>ago</span></div><div class="booking-navlinks"><a onclick="show('trips')">Explore</a><a onclick="show('trips')">Hotels</a><a onclick="show('trips')">Trips</a><a onclick="show('favourites')">Favourites</a></div><div class="notice-nav-actions"><span class="notice-bell">♧</span><span class="notice-avatar">MA</span></div></div></nav><main class="map-full"><div class="map-stage"><div id="travelMap" class="travel-map" aria-label="Interactive travel map"></div><div class="map-status"><b id="mapCountryTitle">Turkey</b><span id="mapCountryCaption">5 traveller favourites</span></div></div><aside class="map-full-control"><div class="eyebrow">EXPLORE THE WORLD</div><h1>Find your next stop</h1><p class="small">Search a country and discover its most-loved places, with live flight prices.</p><div class="map-search"><input id="countrySearch" placeholder="Search a country" onkeydown="if(event.key==='Enter')focusCountry(this.value)"><button class="btn primary" onclick="focusCountry(document.getElementById('countrySearch').value)">Search</button></div><div class="country-list" id="countryList"></div><p class="map-tip">✦ Select a country to zoom in. Tap any pin to see why it belongs in your trip.</p></aside></main>`}
    function renderShell(el){const current=el.parentElement.id;if(current==='explore-map'){el.innerHTML=mapShell();return;}if(current==='booking'){el.innerHTML=bookingShell();return;}if(current==='notifications'){el.innerHTML=notificationShell();return;}if(current==='compare'){el.innerHTML=compareShell();return;}if(current==='reviews'){el.innerHTML=reviewsShell();return;}if(current==='favourites'){el.innerHTML=favouritesShell();return;}el.innerHTML=`<nav><div class="shell" style="display:flex;width:100%;justify-content:space-between;align-items:center"><div class="brand" onclick="show('home')">Voy<span>ago</span></div><div class="navlinks"><a onclick="show('notifications')">🔔 Notifications</a><a onclick="show('profile')">MA&nbsp; Profile</a></div></div></nav><div class="dashboard"><aside class="sidebar">${nav.map(n=>`<div class="side-item ${current===n[0]?'active':''}" onclick="show('${n[0]}')"><span>${n[1]}</span>${n[2]}</div>`).join('')}</aside><main class="main"><div class="eyebrow">YOUR TRAVEL SPACE</div><h1 style="font:700 32px 'Playfair Display';margin:7px 0">${el.getAttribute('title')}</h1><p class="muted">${el.getAttribute('sub')}</p>${pageContent(current)}</main></div>`}
    function pageContent(type){if(type==='explore-map')return `<section class="map-layout"><aside class="map-control"><div class="eyebrow">EXPLORE BY COUNTRY</div><h3>Find your next stop</h3><p class="small">Pick a country to zoom in and reveal its top places.</p><div class="map-search"><input id="countrySearch" placeholder="Search a country" onkeydown="if(event.key==='Enter')focusCountry(this.value)"><button class="btn primary" onclick="focusCountry(document.getElementById('countrySearch').value)">Search</button></div><div class="country-list" id="countryList"></div><p class="map-tip">✦ Tap a pin to see why the place is worth adding to your trip.</p></aside><div class="map-stage"><div class="map-status"><b id="mapCountryTitle">Turkey</b><span id="mapCountryCaption">5 traveller favourites</span></div><div id="travelMap" class="travel-map" aria-label="Interactive travel map"></div></div></section>`;if(type==='trip-details'){const t=selectedTrip;const city=t[0].includes('Athens')?'Athens':'Istanbul';return `<section class="detail-hero"><div><div class="eyebrow" style="color:#ffd0ad">READY-MADE JOURNEY</div><h1>${t[0]}</h1><p>${t[1]} · Carefully paced with handpicked stays, places and food.</p><div style="margin-top:25px;display:flex;gap:20px;font-size:13px"><span>✦ 4.9 traveller rating</span><span>◷ Flexible booking</span></div></div><div class="detail-score"><span class="small">STARTING FROM</span><br><b>${t[2]}</b><br><span class="small">per person · flights not included</span></div></section><section class="detail-layout"><div class="panel" style="margin-top:0"><div class="section-head"><div><div class="eyebrow">DAY BY DAY</div><h2>Your itinerary</h2></div><button class="btn outline" onclick="toast('Your PDF is downloading…')">↓ PDF</button></div><div class="itinerary"><div class="day">DAY 01<br><small>Arrival</small></div><div class="activity"><b>Settle in & discover old town</b><span>Hotel check-in · Welcome walk · Local dinner</span></div><div class="day">DAY 02<br><small>Culture</small></div><div class="activity"><b>The iconic sights of ${city}</b><span>Guided city walk · Local market · Rooftop sunset</span></div><div class="day">DAY 03<br><small>Explore</small></div><div class="activity"><b>A day made for your own pace</b><span>Neighbourhood cafés · Selected activity · Dinner reservation</span></div></div></div><aside class="side-summary"><h3>What’s included</h3><div class="feature">✦<span><b>Curated stays</b>Comfortable, well-located hotels</span></div><div class="feature">✦<span><b>Local experiences</b>Attractions and food picks</span></div><div class="feature">✦<span><b>Flexible itinerary</b>Edit every part whenever you want</span></div><button class="btn primary" style="width:100%;margin-top:18px" onclick="show('booking')">Book this trip</button><button class="btn outline" style="width:100%;margin-top:9px" onclick="toast('Saved to your favourites ♥')">Save to favourites</button></aside></section>`}if(type==='trips'||type==='favourites')return `<div class="panel"><div class="filter"><span class="chip on">All</span><span class="chip">Beach</span><span class="chip">City</span><span class="chip">Adventure</span><span class="chip">Budget friendly</span></div></div><div class="trip-grid" style="margin-top:20px">${trips.map(card).join('')}</div>`; if(type==='create-trip')return `<div class="panel"><div class="filter"><span class="chip on">Destination</span><span class="chip">Dates</span><span class="chip">Style</span><span class="chip">Budget</span></div><div class="trip-grid" style="margin-top:24px"><div class="form-group"><label>Where do you want to go?</label><input placeholder="e.g. Istanbul, Turkey"></div><div class="form-group"><label>How many days?</label><select><option>5 days</option><option>7 days</option><option>10 days</option></select></div><div class="form-group"><label>Your budget</label><select><option>$1,000–$1,500</option><option>$500–$1,000</option><option>$1,500+</option></select></div></div><button class="btn primary" style="margin-top:25px" onclick="show('trip-details')">Meet Joy & generate plan ✦</button></div>`; if(type==='compare')return `<div class="compare" style="margin-top:26px">${trips.slice(0,2).map((t,i)=>`<div class="compare-card"><div class="cover ${t[3]}"><span class="tag">Option ${i+1}</span></div><div class="trip-body"><h3>${t[0]}</h3><div class="row"><span>Total price</span><b>${t[2]}</b></div><div class="row"><span>Guest rating</span><b>4.${9-i} ★</b></div><div class="row"><span>Included days</span><b>${i?4:5} days</b></div><button class="btn ${i?'outline':'primary'}" style="margin-top:12px;width:100%" onclick="toast('Added to your trip')">Choose this trip</button></div></div>`).join('')}</div>`; if(type==='booking')return `<div class="panel"><h2>What would you like to book?</h2>${[['Flight','Cairo → Istanbul','Included in plan · $380'],['Hotel','Golden Horn Suites · 5 nights','$560'],['Airport transfer','Private vehicle','$35']].map((x,i)=>`<div class="row"><span><input type="checkbox" ${i<2?'checked':''}> <b>${x[0]}</b><br><small style="margin-left:22px">${x[1]}</small></span><b>${x[2]}</b></div>`).join('')}<div class="row" style="font-size:16px"><b>Total</b><b>$940</b></div><button class="btn orange" style="margin-top:17px" onclick="toast('Booking request created!')">Continue to payment →</button></div>`; if(type==='reviews')return `<div class="panel"><button class="btn primary" onclick="toast('Review form opened')">+ Write a review</button>${[['Lina M.','A beautiful stay and a perfect location.','5'],['Omar S.','The team made every part easy to plan.','4']].map(r=>`<div class="review"><div class="avatar">${r[0][0]}</div><div><b>${r[0]}</b><div class="stars">${'★'.repeat(r[2])}</div><span class="small">${r[1]}</span></div></div>`).join('')}</div>`; if(type==='notifications')return `<div class="panel">${[['✓','Your hotel booking is confirmed','Golden Horn Suites · 12–16 Sep'],['✈','Your trip starts in 10 days','Check your Istanbul itinerary'],['✦','Your custom plan is ready','Joy has created an updated plan for you']].map(n=>`<div class="notice"><div class="notice-icon">${n[0]}</div><div><b>${n[1]}</b><br><span class="small">${n[2]}</span></div></div>`).join('')}</div>`; if(type==='profile'){const sn=(localStorage.getItem('vamora_user_name')||'').trim();const se=localStorage.getItem('vamora_user_email')||'';return `<div class="panel"><h2>Personal details</h2><div class="trip-grid"><div class="form-group"><label>Full name</label><input value="${sn}"></div><div class="form-group"><label>Email</label><input value="${se}"></div></div><button class="btn primary" style="margin-top:18px" onclick="toast('Profile saved')">Save changes</button></div><div class="panel"><h2>Password & security</h2><p class="muted">Keep your account secure by using a strong password.</p><button class="btn outline" onclick="show('reset')">Update password</button></div>`;}return ''}
